function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2600)}function stopCamera(){stream?.getTracks().forEach(t=>t.stop());stream=null}let transitioning=false,skippedScan=false,manualShape=null,scanEpoch=0;
function canOpenResults(){return skippedScan?manualShape!==null:photos.every(Boolean)&&!analysisPending&&Object.keys(autoFeatures).length>0}
async function go(n){if(busy||transitioning||n===page)return;if((n===2||n===5)&&!canOpenResults())return toast(tr(skippedScan?'请先选择一个脸型':'请先完成正脸和侧脸照片',skippedScan?'Choose a face shape first':'Complete both photos first'));if(n===5){const id=selectedSeason||activeSeason();if(!id||!seasonCanEnter(id))return toast(tr('活动尚未开放或已经结束','This seasonal event is not open'));prepareSeasonDeck(id)}const previousPage=page,entering=n===1&&page!==1,app=$('#app');const fade=!(previousPage===0&&n===1)&&!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches&&typeof app.animate==='function';transitioning=true;if(n!==1)stopCamera();let out=null;try{if(fade){out=app.animate([{opacity:1},{opacity:0}],{duration:160,fill:'forwards'});await out.finished}if(n===1){skippedScan=false;manualShape=null}page=n;render();window.scrollTo(0,0);if(fade){const incoming=app.animate([{opacity:0},{opacity:1}],{duration:220,fill:'forwards'});out.cancel();await incoming.finished;incoming.cancel()}}finally{out?.cancel();transitioning=false}if(entering&&page===1&&!photos.every(Boolean))showGuide()}
function toggleLang(){if(busy||transitioning)return;lang=lang==='zh'?'en':'zh';document.documentElement.lang=lang==='zh'?'zh-CN':'en';const open=$('#modal').dataset.story,season=$('#modal').dataset.season;render();if(season)openSeasonStory(...season.split(':'));else if(open)openStory(...open.split(',').map(Number))}function render(){const has=photos.every(Boolean);$('#favtop').textContent=tr('♡ 收藏夹','♡ Saved')+` (${saved.length+seasonSaved.length})`;$('#language').textContent=lang==='zh'?'中 / EN':'EN / 中';$('#nav').innerHTML=`<button onclick="go(${page===3?favoriteReturn:page===5?2:page===4?1:page===2&&skippedScan?4:Math.max(0,page-1)})" ${page===0?'disabled':''}>← ${tr('返回','Back')}</button><button onclick="next()" ${page===2||page===3||page===5||(page===4&&manualShape===null)?'disabled':''}>${tr('下一页','Next')} →</button><button onclick="go(0)">⌂ ${tr('棱镜仙境入口','Prism Realm Entrance')}</button>`;$('#app').innerHTML=page===0?home():page===1?scan():page===2?library():page===4?manualEntry():page===5?seasonPage():favorites();if(page===1&&stream)connectVideo()}
function home(){return `<section class="hero"><div class="world"></div><div class="cloud c1"></div><div class="cloud c2"></div><div class="cloud c3"></div><div class="stars"></div><div class="hero-content"><div class="eyebrow">A PORTAL TO YOUR MANY SELVES</div><h1 class="beauty-manifesto">YOUR BEAUTY. YOUR WAY.<br><span>你，既是唯一，也是万象。</span></h1><p class="hero-sub">${tr('以原生轮廓，开启万象之美','YOUR OWN CONTOURS. YOUR OWN KIND OF MAGIC.')}</p></div><div class="portal-wrap"><div class="portal-label">${tr('点击我进入体验','Step inside the experience')}</div><button class="portal" aria-label="${tr('开门进入体验','Open the door')}" onclick="enter()"><span class="door"><i class="knob"></i></span></button></div><div class="hero-meta">01 — THE PRISM REALM<br>${tr('不改变你，只让你的光被看见','YOUR FEATURES. YOUR LIGHT. YOUR STORY.')}</div><div class="hero-note">CONTOUR IS A STORY, NOT A STANDARD.<br>${tr('轻欧美 · 原生骨相 · 无限可能','ASIAN CONTOURS · LIMITLESS EXPRESSION')}</div></section>`}function enter(){if(busy)return;busy=true;$('.hero').classList.add('entering');setTimeout(()=>{busy=false;go(1)},2000)}function next(){if(page===0)enter();else if(page===1||page===4)go(2)}
