async function analyze(){
  const epoch=scanEpoch,revision=photoRevision,run=++analysisRun;
  const snapshot=photos.slice();
  const current=()=>epoch===scanEpoch&&revision===photoRevision&&run===analysisRun&&snapshot.every((p,i)=>p===photos[i])&&!skippedScan;
  analysisPending=true;autoFeatures={};featureValues={};shape=null;
  analysisNote=tr('正在根据当前照片更新脸型及轮廓资料…','Updating shape and contours from your current photos…');
  if(page===1)render();
  try{
    if(!snapshot.every(Boolean))throw Error('missing photos');
    const model=await readyModel();if(!current())return;
    const images=await Promise.all(snapshot.map(async src=>{const img=new Image;img.src=src;await img.decode();return img}));if(!current())return;
    // Detect both current images afresh; never reuse landmarks from an earlier pair.
    const results=images.map(img=>model.detect(img));
    if(!current())return;
    if(results.some(r=>r.faceLandmarks?.length!==1))throw Error('Face not detected');
    const points=results.map(r=>r.faceLandmarks[0].map(p=>({x:p.x,y:p.y,z:p.z})));
    const result=deriveFeatures(points[0],points[1],images[0].naturalWidth,images[0].naturalHeight);
    if(!Number.isInteger(result.shape)||result.shape<0||result.shape>=shapes.length||Object.keys(result.features).length!==features.length)throw Error('Invalid estimates');
    if(!current())return;
    photoSizes=images.map(img=>({width:img.naturalWidth,height:img.naturalHeight}));landmarks=points;acceptedResults=results;shape=result.shape;autoFeatures=result.features;
    for(const [i,pair] of Object.entries(autoFeatures))featureValues[i]=pair[lang==='zh'?0:1];
    analysisNote=tr('已根据当前正侧脸照片更新脸型和全部轮廓资料，可修改后继续。','Face shape and all contours now reflect your current front and profile photos. You can edit them before continuing.');
  }catch{
    if(!current())return;
    autoFeatures={};featureValues={};shape=null;
    analysisNote=tr('当前照片未能生成有效判断，请重新拍摄或上传。旧分析已清除。','The current photos could not be analyzed. Retake or upload again; previous estimates have been cleared.');toast(analysisNote);
  }finally{if(current()){analysisPending=false;if(page===1)render()}}
}

function skipScan(){if(transitioning)return;scanEpoch++;invalidateAnalysis();stopCamera();busy=false;analysisPending=false;photos=[null,null];photoSizes=[null,null];landmarks=[null,null];acceptedResults=[null,null];featureValues={};autoFeatures={};analysisNote='';skippedScan=true;manualShape=null;closeBook();return go(4)}
function chooseManualShape(i){manualShape=i;shape=i;render()}
function manualEntry(){return `<section class="page manual-entry"><div class="page-top"><div class="eyebrow">YOUR STORY, YOUR CHOICE</div><h1>${tr('跳过扫描，也能开启故事。','Your story can begin without a scan.')}</h1><p>${tr('选择你想探索的脸型，直接翻阅妆容剧本。本次不会生成 AI 分析结果。','Choose a face shape to explore its makeup stories. No AI analysis is generated for this visit.')}</p></div><div class="profile"><div class="shape-row">${shapes.map((s,i)=>`<button class="shape-btn ${manualShape===i?'selected':''}" onclick="chooseManualShape(${i})">${faceIllustration(i)}${s[lang==='zh'?0:1]}</button>`).join('')}</div><div style="text-align:center;margin-top:35px"><button class="primary" onclick="go(2)" ${manualShape===null?'disabled':''}>${tr('查看妆容剧本','Explore makeup stories')} →</button><button class="secondary" onclick="go(1)">${tr('返回扫描','Return to scanning')}</button></div></div></section>`}

function library(){return `<section class="page hall-page">${realmAtmosphere("hall")}<div class="page-top"><div class="steps"><span>01 ${tr('棱镜仙境入口','PRISM REALM ENTRANCE')}</span><span>02 ${tr('轮廓诊断室','CONTOUR DIAGNOSTIC ROOM')}</span><span class="active">03 ${tr('妆容剧本殿堂','MAKEUP STORY HALL')}</span></div><div class="eyebrow">THE LIBRARY OF YOUR MANY SELVES</div><h1>${tr('每一道轮廓，都不止一种故事。','One face. More than one story.')}</h1><p>${tr('选一本属于此刻的你，让光影成为你的叙事。','Choose the story that feels like you today. Let light and shadow do the storytelling.')}</p></div><div class="library"><div class="shape-summary"><span>${skippedScan?tr('你选择的脸型','YOUR SELECTED SHAPE'):tr('你的轮廓印象','YOUR CONTOUR')}　<strong>${shapes[shape][lang==='zh'?0:1]}</strong></span><span>${tr('轻欧美亚裔轮廓妆 · 放大原生骨相优势','ASIAN CONTOUR · CELEBRATE YOUR OWN STRUCTURE')}</span><button onclick="go(skippedScan?4:1)">${tr('调整轮廓','Edit contours')} ↗</button></div><div class="book-grid">${stories[shape].map((s,j)=>`<div class="book-card"><button class="hardcover" onclick="openStory(${shape},${j})"><span class="volume">VOLUME 0${j+1}</span><div class="sigil">${['⟡','☾','✧'][j]}</div><h3>${s[0]}</h3><p>${lang==='zh'?s[1]:'FENTY PRISM'}</p></button><div class="book-caption">${tr('点击翻开剧本','OPEN YOUR STORY')}</div></div>`).join('')}</div><p class="subtle" style="text-align:center">${tr('不磨平棱角，不定义美丑。你的原生轮廓，本就值得被看见。','No erased angles. No beauty ratings. Your natural structure deserves to be seen.')}</p>${blindBoxSection()}</div></section>`}
function portraitGeometry(i){const size=photoSizes[i];return size&&size.width>0&&size.height>0?size:{width:1000,height:1000}}
