function portraitPanel(i,p){const {width:w,height:h}=portraitGeometry(i);return `<svg class="portrait-map" viewBox="0 0 ${w} ${h}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${tr(i?'侧脸轮廓分析':'正脸轮廓分析',i?'Profile contour analysis':'Front contour analysis')}"><image href="${esc(p)}" x="0" y="0" width="${w}" height="${h}" preserveAspectRatio="none"/>${lines(i)}</svg>`}
function storyOrnaments(title){const name=title.toLowerCase();const theme=/siren|midnight/.test(name)?'lunar':/vintage|retro|enigma/.test(name)?'vintage':/rebel|underground/.test(name)?'spark':'prism';const art={lunar:'<path d="M69 14A29 29 0 1 0 82 65 31 31 0 0 1 69 14Z"/><path d="M12 83q13-10 26 0t26 0 26 0M17 91q12-8 24 0t24 0M88 15v14m-7-7h14M22 12v10m-5-5h10"/>',vintage:'<path d="M14 84q8-24 35-30t35-38M19 84q28-7 35-33t30-36M29 71q-21-8-15-26 24 3 15 26ZM47 56q-19-16-6-28 21 10 6 28ZM60 41q-6-22 13-27 12 19-13 27Z"/><path d="m63 78 9-8 10 8-10 8Zm9-8V58"/>',spark:'<path d="m51 12 9 29 29 10-29 10-9 29-10-29-29-10 29-10Z"/><path d="M14 18v15m-7-7h15M82 77v15m-7-7h15M55 30l-8 18 12 1-15 24"/>',prism:'<path d="m51 10 28 24-4 36-24 22-25-22-4-36ZM51 10l-9 30 9 52 10-52 18-6M22 34l20 6h19M26 70l25-9 24 9"/><path d="M12 15v12m-6-6h12M86 75v15m-7-7h14"/>'};return ['top','bottom'].map(position=>`<svg class="story-ornament ornament-${position}" viewBox="0 0 100 100" fill="none" aria-hidden="true" data-theme="${theme}">${art[theme]}</svg>`).join('')}

function openStory(si,j,season=null){const s=season?season.s:stories[si][j];$('#modal').dataset.story=si+','+j;if(season)$('#modal').dataset.season=season.eventId+':'+season.storyId;else delete $('#modal').dataset.season;$('#modal').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeBook()"><button class="close-modal" onclick="closeBook()" aria-label="${tr('关闭书本','Close book')}">×</button><article class="open-book" role="dialog" aria-modal="true" aria-label="${s[0]}" tabindex="-1"><div class="book-left"><p class="book-kicker">YOUR CONTOUR ATLAS / 0${si+1}</p>${photos.map((p,i)=>`<div><div class="photo-label">0${i+1} — ${tr(i?'侧脸轮廓':'正脸轮廓',i?'SIDE PROFILE':'FRONT PORTRAIT')}</div><div class="book-photo ${mirrorModes[i]?'is-mirrored':''}">${p?` ${portraitPanel(i,p)}`:`<div class="photo-placeholder">✧<span>${tr('未拍摄照片','No photo captured')}</span></div>`}</div></div>`).join('')}<p class="atlas-note">${skippedScan?tr('已跳过扫描，按你选择的脸型展示剧本。','Scanning skipped. Stories follow your selected face shape.'):tr('线条来自可定位的照片关键点，仅为二维视觉参考；无法定位时展示原图。','Lines use detected photo landmarks as 2D references. Original photos appear when no landmarks are available.')}</p>${contourSummary(si)}</div><div class="book-right">${storyOrnaments(s[0])}${season?`<div class="season-book-heading"><div class="season-title-block"><h2>${s[0]}</h2><h3>${tr(s[1],season.event.en+' contour story')}</h3></div>${seasonStoryBadge(season)}</div>`:`<div class="book-kicker">FENTY PRISM · VOLUME 0${j+1}</div><h2>${s[0]}</h2><h3>${lang==='zh'?s[1]:shapes[si][1]+' contour story'}</h3>`}<h4>${tr('序章 · 你的故事','PROLOGUE · YOUR STORY')}</h4><p>${s[lang==='zh'?2:3]}</p><h4>${tr('骨相策略','CONTOUR STRATEGY')}</h4><p>${s[lang==='zh'?4:5]}</p><h4>${tr('轮廓重点 · 光影落点','LIGHT & SHADOW NOTES')}</h4><p>${s[lang==='zh'?6:7]}</p>${season?seasonalMakeupNotes(season.story):makeupNotes(si,j)}<h4>THE FENTY EDIT</h4><div class="product-list">${season?s[8].map(seasonProductCard).join(''):[...new Set([...s[8],'Cheeks Out Freestyle Cream Blush'])].map(productCard).join('')}</div><p class="editorial-note">${tr('产品系列参考；具体色号需根据肤色与底调另行选择。独立商赛概念 demo，非 Fenty 官方网站。','Product-family references; shades require skin-tone and undertone matching. Independent competition concept, not an official Fenty website.')}</p><button class="primary" onclick="${season?`saveSeasonStory('${season.eventId}','${season.storyId}')`:`saveStory(${si},${j})`}">${(season?seasonSaved.some(x=>x.event===season.eventId&&x.story===season.storyId):saved.some(x=>x.si===si&&x.j===j))?tr('✓ 已收藏','✓ Saved'):tr('♡ 收藏这本剧本','♡ Save this story')}</button></div></article></div>`;$('.open-book').focus();document.body.style.overflow='hidden'}function closeBook(){$('#modal').innerHTML='';delete $('#modal').dataset.story;delete $('#modal').dataset.season;document.body.style.overflow=''}document.addEventListener('keydown',e=>{if(e.key==='Escape')closeBook();if(e.key==='Tab'&&$('.open-book')){const list=[...$('#modal').querySelectorAll('button,[tabindex]')];const a=list[0],b=list[list.length-1];if(e.shiftKey&&document.activeElement===a){e.preventDefault();b.focus()}else if(!e.shiftKey&&document.activeElement===b){e.preventDefault();a.focus()}}});function saveStory(si,j){if(!saved.some(x=>x.si===si&&x.j===j)){saved.push({si,j});persist()}toast(tr('剧本已收藏在此浏览器中（不保存照片）','Saved in this browser, without photos'));openStory(si,j);$('#favtop').textContent=tr('♡ 收藏夹','♡ Saved')+` (${saved.length+seasonSaved.length})`}function persist(){try{localStorage.setItem('prism-books',JSON.stringify(saved))}catch{toast(tr('当前浏览器无法持久保存收藏','This browser cannot retain saved stories'))}}function showFavorites(){if(busy)return;if(page!==3)favoriteReturn=page;closeBook();go(3)}function favorites(){return `<section class="page"><div class="page-top"><div class="eyebrow">YOUR PERSONAL LIBRARY</div><h1>${tr('收藏你的万种可能。','Keep your favourite selves.')}</h1><p>${tr('收藏保存在当前浏览器；照片不会保存到收藏夹。','Stories are saved in this browser. Photos are never stored in your saved collection.')}</p></div><div class="favorites-list">${saved.length+seasonSaved.length?seasonFavoriteRows()+saved.map((x,n)=>`<div class="favorite-row"><div><h3>${stories[x.si][x.j][0]}</h3><span class="subtle">${tr(stories[x.si][x.j][1],shapes[x.si][1])} · ${shapes[x.si][lang==='zh'?0:1]}</span></div><div><button class="secondary" onclick="openStory(${x.si},${x.j})">${tr('翻开','Open')} ↗</button><button class="secondary" onclick="removeSaved(${n})">${tr('移除','Remove')}</button></div></div>`).join(''):`<div class="empty">✧<br><br>${tr('故事尚未入藏，去翻开你的第一本剧本吧。','Your library awaits its first story.')}<br><br><button class="secondary" onclick="go(${canOpenResults()?2:1})">${tr('探索剧本','Explore stories')} →</button></div>`}</div></section>`}function removeSaved(n){saved.splice(n,1);persist();render()}
function mirrorControl(i){return `<div class="mirror-control" role="group" aria-label="${tr('照片方向','Photo orientation')}"><button type="button" aria-pressed="${!mirrorModes[i]}" onclick="setMirror(${i},false)">${tr('不镜像','Original')}</button><button type="button" aria-pressed="${mirrorModes[i]}" onclick="setMirror(${i},true)">${tr('镜像','Mirror')}</button></div>`}
function setMirror(i,value){mirrorModes[i]=value;const card=$('#camera'+i);if(!card)return;card.querySelector('video,img')?.classList.toggle('is-mirrored',value);card.querySelector('.mirror-control').outerHTML=mirrorControl(i)}
const productCatalog={
'Gloss Bomb Universal Lip Luminizer':{image:"products/gloss-bomb.jpg",shade:"Fu$$y",url:'https://fentybeauty.com/en-sg/collections/award-winners/products/gloss-bomb-universal-lip-luminizer-fuy',zh:'亮泽唇蜜，带细闪且不黏腻；配方含乳木果脂与维生素 E。单独薄涂或叠在唇膏中央，为剧本加入柔亮唇部焦点。',en:'A non-sticky, shimmering lip gloss with shea butter and vitamin E. Wear a thin layer alone or at the centre of lipstick for a softly luminous focal point.'},
'Match Stix Contour Skinstick':{image:"products/match-stix.jpg",shade:"Amber",url:'https://fentybeauty.com/en-sg/products/match-stix-contour-skinstick-amber',zh:'轻盈膏转粉质地，哑光妆效，可叠加、易晕染。棒状设计适合沿下颌或颧下小范围定位修容。',en:'A lightweight cream-to-powder contour with a matte finish. Buildable and blendable; the stick allows precise placement beneath the cheekbone or jaw.'},
'Fenty Icon Velvet Liquid Lipstick':{image:"products/icon-velvet.jpg",shade:"RiRi",url:'https://fentybeauty.com/en-in/products/fenty-icon-velvet-liquid-lipstick-riri',zh:'绵密慕斯般的液体唇膏，显色浓郁，呈丝绒哑光妆效。少量薄涂后晕开唇缘，呼应剧本的低饱和氛围。',en:'Richly pigmented liquid lipstick with a whipped texture and velvet-matte finish. Use a thin layer and soften the edges for this story’s muted mood.'},
'Killawatt Freestyle Highlighter':{image:"products/killawatt.jpg",shade:"Lightning Dust / Fire Crystal",url:'https://fentybeauty.com/products/killawatt-freestyle-highlighter-lightning-dustfire-crystal',zh:'轻盈持妆的膏粉混合质地，细闪光泽可从柔和叠加至鲜明。以少量点亮眉骨或颧骨，让光影保留层次。',en:'A weightless, longwear cream-powder highlighter with fine shimmer, from subtle to intense. Use a small amount on the brow or cheekbone for layered light.'},
'Diamond Bomb All-Over Diamond Veil':{image:"products/diamond-bomb.jpg",shade:"How Many Carats?!",url:'https://fentybeauty.com/en-sg/products/diamond-bomb-all-over-diamond-veil-how-many-carats',zh:'带弹性的啫喱触感粉质，呈细密钻石闪耀妆效。用于本剧本时只轻点局部，保留闪光与肤质的对比。',en:'A bouncy, jelly-like powder with a diamond-sparkle finish. For this story, tap sparingly onto a small area to contrast sparkle with natural texture.'},
'Eaze Drop Lightweight Blurring Skin Tint':{image:"products/eaze-drop.jpg",shade:"1",url:'https://fentybeauty.com/en-sg/products/eaze-drop-lightweight-blurring-skin-tint-1',zh:'轻盈、轻至中度可叠加遮盖，QuickBlur 配方带来柔焦感。薄铺均匀肤色，让原生轮廓与肤质仍然可见。',en:'Lightweight, buildable light-to-medium coverage with a QuickBlur soft-focus effect. Apply a sheer layer to even tone while retaining natural texture and contours.'},
'Cheeks Out Freestyle Cream Blush':{image:"products/cheeks-out.jpg",shade:"Rosé Latte",url:'https://fentybeauty.com/en-bn/products/cheeks-out-freestyle-cream-blush-rose-latte',zh:'轻盈、不油腻的膏状腮红，色彩通透、可叠加，易融入肌肤。依下方腮红落点少量轻拍，保留自然气色。',en:'An airy, non-greasy cream blush with sheer, buildable colour that blends into skin. Tap a little along the placement suggested in your makeup notes.'}
};
function productCard(name){const p=productCatalog[name];if(!p)return '';const copy=tr(p.zh,p.en);const match=copy.match(/^(.+?[。.!?])\s*([\s\S]*)$/);const detail=match?match[1]:copy,usage=match?match[2]:'';return `<article class="product-card product-with-image"><figure class="product-figure"><a class="product-image-link" href="${p.url}" target="_blank" rel="noopener noreferrer" aria-label="${esc(name)}"><img src="${p.image}" alt="${esc(name+' — '+p.shade)}" width="640" height="640" loading="lazy" decoding="async"></a><figcaption>${tr('图示色号','Shown shade')} · ${esc(p.shade)}</figcaption></figure><div class="product-copy"><a class="product-title" href="${p.url}" target="_blank" rel="noopener noreferrer">${esc(name)} <span aria-hidden="true">↗</span></a><div class="product-detail"><span>${tr('产品特点','FORMULA')}</span><p>${esc(detail)}</p></div>${usage?`<div class="product-detail"><span>${tr('剧本用法','IN THIS STORY')}</span><p>${esc(usage)}</p></div>`:''}<small>${tr('产品图片与特点：Fenty 官网','Product imagery & formula: Fenty official site')}</small></div></article>`}

const makeupGuides=[
[['眉形','眉峰保留自然弧度，眉尾略微延长；用柔和线条增加纵向层次。','Brows','Keep a natural arch and extend the tail slightly for gentle vertical definition.'],['腮红','从颧骨下方轻斜向太阳穴晕开，少量多次，保留脸颊的柔和饱满感。','Blush','Diffuse a little colour diagonally toward the temples, keeping the cheeks softly full.'],['光影','沿下颌下缘轻扫阴影，眉骨与鼻梁点式提亮，增加边界而不压窄脸。','Light & shadow','Shade beneath the jaw boundary; add small brow and bridge highlights without narrowing the face.']],
[['眉形','柔和微弯，眉峰不过尖，眉尾自然延伸；保留下颌的力量感。','Brows','Use a soft curve and a gentle peak, letting the natural jaw remain strong.'],['腮红','在颧骨上方以小范围圆弧晕开，避开下颌角，让色彩柔和衔接棱角。','Blush','Blend a small rounded wash above the cheekbone, away from the jaw angle.'],['光影','顺着下颌外缘轻扫，不覆盖拐角；提亮面中与眉骨，引导视线上移。','Light & shadow','Follow the outer jaw without covering the angle; bring light to the mid-face and brow.']],
[['眉形','选择自然弧度与适中眉峰，眉尾柔和收束，让眉眼与颧骨互相呼应。','Brows','Choose a natural arch with a moderate peak and a soft tail to echo the cheekbones.'],['腮红','在颧骨下方少量铺色，向内轻柔晕开；颧骨顶点可按剧本保留定点光泽。','Blush','Place a little colour beneath the cheekbone and diffuse inward, keeping apex light as the story suggests.'],['光影','颧下修容薄而柔，额头与下巴少量提亮；保留颧骨辨识度，不画整条深色阴影。','Light & shadow','Keep cheek shadow sheer; balance with forehead and chin light, retaining distinctive cheekbones.']],
[['眉形','以较平直、柔和的眉形横向延伸，眉峰不过高，眉尾自然收束。','Brows','Extend a softly straight brow horizontally, keeping the peak low and the tail natural.'],['腮红','从苹果肌向面侧横向轻扫，位置不过低，让面中有舒展的色彩与呼吸感。','Blush','Sweep lightly outward from the apples, keeping colour high enough for an open mid-face.'],['光影','额头两侧与下巴适量提亮，颧下阴影柔和过渡；不磨平最有辨识度的颧骨。','Light & shadow','Light the forehead sides and chin; diffuse cheek shadow while preserving the cheekbones.']]
];
function makeupNotes(si,j){const finish=[['日常力度：少量多次，边缘充分晕开，让原生骨相先被看见。','Everyday intensity: build slowly and diffuse the edges so your natural structure leads.'],['复古力度：腮红与唇色保持同一低饱和色系，让眉眼成为叙事中心。','Vintage intensity: keep blush and lips in a related muted palette, letting brows and eyes tell the story.'],['夜间力度：只提高一处光影对比，其余区域保持轻薄留白。','Evening intensity: strengthen one light-and-shadow accent and keep the rest sheer.']][j];return `<section class="makeup-notes"><h4>${tr('上妆笔记 · 眉形 / 腮红 / 光影','MAKEUP NOTES · BROWS / BLUSH / LIGHT')}</h4>${makeupGuides[si].map(t=>`<div class="makeup-tip"><strong>${t[lang==='zh'?0:2]}</strong><p>${t[lang==='zh'?1:3]}</p></div>`).join('')}<p class="finish-note">${tr(...finish)}</p></section>`}
const detailLabels=[
[['宽度','高度','额骨起伏'],['Width','Height','Forehead relief']],
[['眉骨立体度','眼窝落差'],['Brow projection','Orbital contrast']],
[['深浅'],['Apparent depth']],
[['鼻起点','鼻梁走向','鼻骨宽度','鼻基底'],['Nose root','Bridge line','Bridge width','Nose base']],
[['位置','突出程度','颧弓宽度'],['Position','Projection','Cheek span']],
[['下颌拐点','下颌宽度','下颌线条','下巴长度','下巴形状'],['Jaw turn','Jaw width','Jawline','Chin length','Chin shape']],
[['面中长度','饱满度'],['Mid-face length','Fullness']],
[['侧面走向'],['Profile alignment']],
[['横纵比例','参考比值'],['Proportions','Reference ratio']]
];
function contourSummary(si){const entries=Object.entries(featureValues).filter(([,v])=>v);return `<section class="contour-report"><div class="report-heading"><span>${tr('你的轮廓档案','YOUR CONTOUR ATLAS')}</span><strong>${shapes[si][lang==='zh'?0:1]}</strong><small>${skippedScan?tr('手动选择','Manually selected'):tr('AI 照片视觉估计 · 可修改','AI photo estimates · editable')}</small></div>${entries.length?`<div class="report-grid">${entries.map(([i,v])=>`<article class="report-item"><h4>${esc(features[i][lang==='zh'?0:1].split(/[:：]/)[0])}<small>${tr([0,8].includes(+i)?'比例参考':'视觉参考',[0,8].includes(+i)?'Proportions':'Visual')}</small></h4><dl>${String(v).split(/\s*\/\s*/).map((part,k)=>`<div><dt>${esc(detailLabels[i]?.[lang==='zh'?0:1]?.[k]||tr('补充','Note'))}</dt><dd>${esc(part)}</dd></div>`).join('')}</dl></article>`).join('')}</div><p class="report-caveat">${tr('以上来自二维照片。眉骨、眼窝、鼻基底等深度信息受光线与软组织影响较大，仅作妆容参考。','These are 2D photo observations. Depth cues are sensitive to light and soft tissue and serve only as makeup references.')}</p>`:`<p class="report-caveat">${tr('已跳过扫描，本剧本依据你选择的脸型展示。','Scanning was skipped. This story follows your selected shape.')}</p>`}<button class="report-edit" onclick="closeBook();go(skippedScan?4:1)">${tr('修改我的轮廓档案','Edit my contour profile')} ↗</button></section>`}
window.addEventListener('pagehide',stopCamera);window.addEventListener('focus',refreshSeasonDate);document.addEventListener('visibilitychange',refreshSeasonDate);if(typeof setInterval==='function')setInterval(refreshSeasonDate,60000);render();
